#!/usr/bin/env node
/**
 * Verify the coverage summary generated by a CRA application.
 *
 * CRA's package-level `coverageThreshold` already fails the test process, but a
 * separate check makes the generated evidence explicit in CI and catches a
 * report that was never written. It also re-checks the API directory floor so
 * a passing global average cannot hide an untested transport layer.
 */

import fs from 'node:fs';
import path from 'node:path';

const appRoot = process.cwd();
const packagePath = path.join(appRoot, 'package.json');
const summaryPath = path.join(appRoot, 'coverage', 'coverage-summary.json');
const manifest = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
const thresholds = manifest.jest?.coverageThreshold;

if (!thresholds?.global || !thresholds['./src/api/']) {
  throw new Error(`${packagePath} must define global and ./src/api/ coverage thresholds`);
}

if (!fs.existsSync(summaryPath)) {
  throw new Error(`Missing ${summaryPath}; run npm run test:coverage first`);
}

const summary = JSON.parse(fs.readFileSync(summaryPath, 'utf8'));
const metrics = ['statements', 'branches', 'functions', 'lines'];
const failures = [];

function check(label, actual, floor) {
  for (const metric of metrics) {
    const value = actual?.[metric];
    const pct = typeof value === 'number' ? value : value?.pct;
    if (typeof pct !== 'number' || pct < floor[metric]) {
      failures.push(`${label}: ${metric} ${pct ?? 'n/a'} < ${floor[metric]}`);
    }
  }
}

check('global', summary.total, thresholds.global);

const apiEntries = Object.entries(summary).filter(([file]) =>
  file.split(String.fromCharCode(92)).join('/').includes('/src/api/')
);
const apiTotal = metrics.reduce((total, metric) => {
  const totals = apiEntries.reduce(
    (sum, [, entry]) => ({
      covered: sum.covered + (entry[metric]?.covered || 0),
      total: sum.total + (entry[metric]?.total || 0),
    }),
    { covered: 0, total: 0 }
  );
  total[metric] = totals.total ? (totals.covered / totals.total) * 100 : 100;
  return total;
}, {});

check('./src/api/', apiTotal, thresholds['./src/api/']);

if (failures.length) {
  throw new Error(`Coverage gate failed:\n${failures.join('\n')}`);
}

process.stdout.write(`Coverage gate passed: ${apiEntries.length} API files checked\n`);
